class BookMyShow:
    def __init__(self, n: int, m: int):
        self.n, self.m = n, m
        self.s = [0] * (4 * n)
        self.mx = [0] * (4 * n)
    def _upd(self, node, l, r, i, v):
        if l == r:
            self.s[node] += v; self.mx[node] += v; return
        mid = (l + r) // 2
        self._upd(node*2, l, mid, i, v) if i <= mid else self._upd(node*2+1, mid+1, r, i, v)
        self.s[node] = self.s[node*2] + self.s[node*2+1]
        self.mx[node] = max(self.mx[node*2], self.mx[node*2+1])
    def _sum(self, node, l, r, ql, qh):
        if qh < l or r < ql: return 0
        if ql <= l and r <= qh: return self.s[node]
        mid = (l + r) // 2
        return self._sum(node*2, l, mid, ql, qh) + self._sum(node*2+1, mid+1, r, ql, qh)
    def _find(self, node, l, r, k, row):
        if self.mx[node] > self.m - k or l > row: return -1
        if l == r: return l
        mid = (l + r) // 2
        res = self._find(node*2, l, mid, k, row)
        return res if res != -1 else self._find(node*2+1, mid+1, r, k, row)
    def gather(self, k: int, maxRow: int) -> List[int]:
        r = self._find(1, 0, self.n - 1, k, maxRow)
        if r == -1: return []
        c = self._sum(1, 0, self.n - 1, r, r)
        self._upd(1, 0, self.n - 1, r, k)
        return [r, c]
    def scatter(self, k: int, maxRow: int) -> bool:
        if (maxRow + 1) * self.m - self._sum(1, 0, self.n - 1, 0, maxRow) < k:
            return False
        while k > 0:
            r = self._find(1, 0, self.n - 1, 1, maxRow)
            free = self.m - self._sum(1, 0, self.n - 1, r, r)
            t = min(free, k)
            self._upd(1, 0, self.n - 1, r, t)
            k -= t
        return True

