        if (l == r) { s[node] += v; mx[node] += v; return; }
        int mid = (l + r) / 2;
        if (i <= mid) upd(node*2, l, mid, i, v); else upd(node*2+1, mid+1, r, i, v);
        s[node] = s[node*2] + s[node*2+1];
        mx[node] = max(mx[node*2], mx[node*2+1]);
    }
