        s = new long[4 * n]; mx = new long[4 * n];
    }
    private void upd(int node, int l, int r, int i, long v) {
        if (l == r) { s[node] += v; mx[node] += v; return; }
        int mid = (l + r) / 2;
        if (i <= mid) upd(node*2, l, mid, i, v); else upd(node*2+1, mid+1, r, i, v);
        s[node] = s[node*2] + s[node*2+1];
        mx[node] = Math.max(mx[node*2], mx[node*2+1]);
    }
    private long qsum(int node, int l, int r, int ql, int qh) {
        if (qh < l || r < ql) return 0;
        if (ql <= l && r <= qh) return s[node];
        int mid = (l + r) / 2;
        return qsum(node*2, l, mid, ql, qh) + qsum(node*2+1, mid+1, r, ql, qh);
    }
    private int find(int node, int l, int r, long k, int row) {
        if (mx[node] > m - k || l > row) return -1;
        if (l == r) return l;
        int mid = (l + r) / 2;
        int res = find(node*2, l, mid, k, row);
        return res != -1 ? res : find(node*2+1, mid+1, r, k, row);
    }
