        upd(1, 0, n - 1, r, k);
        return new int[]{r, c};
    }
    public boolean scatter(int k, int maxRow) {
        if ((long)(maxRow + 1) * m - qsum(1, 0, n - 1, 0, maxRow) < k) return false;
        while (k > 0) {
            int r = find(1, 0, n - 1, 1, maxRow);
            long free = m - qsum(1, 0, n - 1, r, r);
            long t = Math.min(free, (long) k);
            upd(1, 0, n - 1, r, t);
            k -= t;
        }
        return true;
    }
}

