// Sqrt-decomposition variant: per-row array plus block totals/maxima.
class BookMyShow {
    int n; long long m;
    vector<long long> used, bt, bx;
    int B;
public:
    BookMyShow(int n, int m) : n(n), m(m), used(n, 0) {
        B = max(1, (int)sqrt((double)n));
        bt.assign((n + B - 1) / B, 0);
        bx.assign((n + B - 1) / B, 0);
    }
    vector<int> gather(int k, int maxRow) {
        for (int r = 0; r <= min(maxRow, n - 1); r++)
            if (m - used[r] >= k) {
                int c = (int)used[r];
                used[r] += k; bt[r / B] += k;
                bx[r / B] = max(bx[r / B], used[r]);
                return {r, c};
            }
        return {};
    }
    bool scatter(int k, int maxRow) {
        long long cap = 0;
        for (int r = 0; r <= maxRow; r++) cap += m - used[r];
        if (cap < k) return false;
        for (int r = 0; r <= maxRow && k > 0; r++) {
            long long take = min(m - used[r], (long long)k);
            used[r] += take; bt[r / B] += take;
            bx[r / B] = max(bx[r / B], used[r]);
            k -= (int)take;
        }
        return true;
    }
};

